const { writeFileSync } = await import('node:fs');
const html = process.env.HTML_INPUT;
if (!html) { throw new Error('Missing HTML input'); }
const path = '/tmp/input.html';
writeFileSync(path, html);
globalThis.htmlPath = path;

const { JSDOM } = await import('jsdom');
const { default: generatePDF } = await import('react-to-pdf');
const { readFileSync } = await import('node:fs');
const html = readFileSync(globalThis.htmlPath, 'utf8');
const dom = new JSDOM(html);
const element = dom.window.document.body;
const result = await generatePDF(element, { filename: 'out.pdf', method: 'blob' });
let blob = result && result.blob ? result.blob : result;
if (!blob) { throw new Error('No PDF blob produced'); }
const arrayBuffer = await blob.arrayBuffer();
const base64 = Buffer.from(arrayBuffer).toString('base64');
globalThis.pdfBase64 = base64;
